import type { ControlScheme } from '../contracts';
import { applyMatchStatistics } from '../gameplay/MatchRewards';
import type { MatchRewardInput } from '../gameplay/MatchRewards';
import { syncUnlockedCosmetics } from '../player/cosmetics';
import { addXp, xpForLevel } from '../player/progression';
import type { PlayerProfile, PlayerSettings, QualityPreset } from '../player/types';

/**
 * What a finished match reports back about the local player: the reward inputs
 * plus the XP already granted by MatchRewards and the rating RatingSystem produced.
 */
export interface MatchOutcome extends MatchRewardInput {
  xp: number;
  ratingAfter?: number;
}

/** Menu-facing view of the stored profile; structurally the UI `ProfileDTO`. */
export interface ProfileSummary {
  id: string;
  displayName: string;
  kind: 'human';
  ballStyleId: string;
  rating: number;
  level: number;
  /** XP earned inside the current level, not the lifetime total. */
  xp: number;
  /** XP the current level spans; 0 once the player is maxed out. */
  xpNext: number;
  matches: number;
  wins: number;
  bestRound: number;
}

/** Settings as the menu screen models them (percent volume, ui control ids). */
export interface UiSettingsView {
  controlScheme: ControlScheme;
  quality: QualityPreset;
  volume: number;
  reducedMotion: boolean;
}

export function profileSummary(profile: PlayerProfile): ProfileSummary {
  const level = profile.progression.level;
  const floor = xpForLevel(level);
  const ceiling = xpForLevel(level + 1);
  return {
    id: profile.id,
    displayName: profile.displayName,
    kind: 'human',
    ballStyleId: profile.cosmetics.ballId,
    rating: Math.round(profile.rating),
    level,
    xp: Math.max(0, profile.progression.xp - floor),
    xpNext: Math.max(0, ceiling - floor),
    matches: profile.statistics.matchesPlayed,
    wins: profile.statistics.matchesWon,
    bestRound: profile.statistics.bestRoundStrokes ?? 0,
  };
}

export function settingsToUi(settings: PlayerSettings): UiSettingsView {
  return {
    controlScheme: settings.controlScheme === 'charge' ? 'hold-to-charge' : 'drag-power',
    quality: settings.qualityPreset,
    volume: Math.round(Math.max(0, Math.min(1, settings.masterVolume)) * 100),
    reducedMotion: settings.reducedMotion === true,
  };
}

/** Folds the menu form back into the stored settings, keeping untouched fields. */
export function uiToSettings(view: UiSettingsView, previous: PlayerSettings): PlayerSettings {
  const percent = Number.isFinite(view.volume) ? view.volume : 0;
  return {
    ...previous,
    controlScheme: view.controlScheme === 'hold-to-charge' ? 'charge' : 'drag',
    qualityPreset: view.quality,
    masterVolume: Math.max(0, Math.min(1, percent / 100)),
    reducedMotion: view.reducedMotion === true,
  };
}

/** Applies one finished match: XP, level, rating, lifetime statistics, unlocks. */
export function applyMatchOutcome(profile: PlayerProfile, outcome: MatchOutcome, now = new Date()): PlayerProfile {
  const progression = addXp(profile.progression, outcome.xp);
  const rating =
    typeof outcome.ratingAfter === 'number' && Number.isFinite(outcome.ratingAfter)
      ? Math.max(0, Math.round(outcome.ratingAfter))
      : profile.rating;
  return {
    ...profile,
    rating,
    progression,
    statistics: applyMatchStatistics(profile.statistics, outcome),
    cosmetics: syncUnlockedCosmetics(profile.cosmetics, progression.level),
    updatedAt: now.toISOString(),
  };
}
